import { connect } from "react-redux";
import Layout from "hocs/layouts/Layout";
import { Link, useParams } from "react-router-dom";
import { useEffect } from "react";
import { get_blog } from "redux/actions/blog/blog";
import moment from "moment";
import DOMPurify from 'dompurify';

function PostDetail({
    get_blog,
    post
}) {
    const params = useParams()
    const slug = params.slug

    useEffect(()=>{
        window.scrollTo(0, 0)
        get_blog(slug)

        window.addEventListener('resize', adjustSize);
        return () => {
            window.addEventListener('resize', adjustSize);
        }
    }, [get_blog, slug]);

    function adjustSize(){
        const iframe = document.querySelector('iframe')

        if (iframe){
            var screenWidth = window.innerWidth;
            var screenHeight = window.innerHeight;
        
            if (screenWidth >= 1316) {
                iframe.width = '600';
                iframe.height = '350';
            } else if (screenWidth >= 820) {
                iframe.width = '500';
                iframe.height = '300';
            } else if (screenWidth >= 617) {
                iframe.width = '400';
                iframe.height = '250';
            }else if (screenWidth >= 474){
                iframe.width = '300';
                iframe.height = '200';
            }else if (screenWidth >= 316){
                iframe.width = '200';
                iframe.height = '175';
            }else{
                iframe.width = '175';
                iframe.height = '150';
            }
            
        };
    };
    
    return (
        <Layout>
            <section className="post-detail" >
                {
                    post&&post ?

                    <div>
                        <div className="img-post" >
                            <img src={`${post.thumbnail}`}  alt="post img" />
                        </div>

                        <h2 className="h2">{post.title}</h2>
                        <Link className="a" to={`/category/${post.category.slug}`}><span className="span">{post.category.name}</span></Link>    
                        <span className="span">{moment(post.published).format('LL')}</span>
                        <span className="span">{post.time_read} min read</span>
                        <p className="p">{post.description}</p>
                        <p className="editor" dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(post.content, {
                                            ADD_TAGS: ['iframe'],
                                            ADD_ATTR: ['allow', 'allowfullscreen', 'frameborder', 'scrolling', 'src'],
                                            ADD_URI_SAFE_ATTR: ['src'],
                                            FORBID_TAGS: ['script'],
                        })}} /> 
                    </div>
                    :
                    <div></div>
                }
                    
                
            </section>
        </Layout>
    )
}

const mapStateToProps=state=>({
    post: state.blog.post
})

export default connect(mapStateToProps,{
    get_blog,
})(PostDetail)