import SmallSetPagination from "components/pagination/SmallSetPagination"
import moment from "moment"
import { Link } from "react-router-dom"

function PostBody({posts, list_page, count}){
    
    return (
        <div className="blog-container">
        {
            posts&&posts.map(post => (
            <div key={post.id} className="blog-box">
                
                <Link to={`/blog/${post.slug}`} className="img-box" >
                        <img src={`${process.env.REACT_APP_API_URL}/${post.thumbnail}`} alt="post img" />
                </Link>
                
                <div className="blog-content">
                    <Link to={`/blog/${post.slug}`}><h2>{post.title.length > 150 ? post.title.slice(0,149): post.title}</h2></Link>
                    <Link to={`/category/${post.category.slug}`}><span>{post.category.name}</span></Link>   
                    <span>{moment(post.published).format('LL')}</span>
                    <span>{post.time_read} min read</span>
                    <p>{post.description.length  > 200 ? post.description.slice(0,199) + '...': post.description}</p>
                </div>
                <div className="blog-layer">
                    <Link to={`/blog/${post.slug}`}><i className='bx bx-link-external'></i></Link>
                </div>
            </div>
            ))
        }
        <SmallSetPagination list_page={list_page} list={posts} count={count} />
    </div>
    
    )
}

export default PostBody