import { Link, NavLink, useLocation, useNavigate } from "react-router-dom"
import { useState } from 'react'
import axios from "axios"
import { useDispatch } from "react-redux";
import { GET_PORTFOLIO_LIST_FAIL, GET_PORTFOLIO_LIST_SUCCESS } from "redux/actions/portfolio/types";

function FiltersHeader({
    setLoading
}){

    const [formData, setFormData] = useState({
        category: 'all',
        status: 'all'
    })
    const {
        category,
        status,
    } = formData;

    const dispatch = useDispatch()

    const onSubmit = (e) => {
        setLoading(true)

        let data = null

        if(e.target.name === 'category'){
            setFormData({ ...formData, category: e.target.value })
            data = {
                'category': e.target.value,
                'status': status
            }
        }
        if(e.target.name === 'status'){
            setFormData({ ...formData, status: e.target.value })
            data = {
                'category': category,
                'status': e.target.value
            }
        }
        const fetchFilterData = async() => {
            const config = {
                headers: {
                    'Accept': 'application/json',
                }
            };

            try{
                const res = await axios.post(`${process.env.REACT_APP_API_URL}/api/portfolio/filter`, 
                data, 
                config
                )

                if (res.status === 200){
                    setLoading(false)
                    dispatch({
                        type: GET_PORTFOLIO_LIST_SUCCESS,
                        payload: res.data,
                    });
                }else{
                    setLoading(false)
                    dispatch({
                        type: GET_PORTFOLIO_LIST_FAIL,
                    });
                }
            }catch(err){
                setLoading(false)
                dispatch({
                    type: GET_PORTFOLIO_LIST_FAIL,
                });
            }
        };
        fetchFilterData();
    }

    const [open, setOpen] = useState(false)

    return (
        <div className="second-header">
            <div className='icon-box'>
                <i onClick={open ? ()=>{setOpen(false)}:()=>{setOpen(true)}} className={`bx ${open ? 'bx-x icon-2':'bx-menu icon-2'}`} id="icon"></i>
            </div>

            {
                open ?
                <form action="#" className="filters-box active-box" encType="multipart/form-data">

                    
                </form>
                :
                <form action="#" className="filters-box" encType="multipart/form-data">
                        
                        <div className="header-heading">
                            <h4>Filter by category</h4>

                            <select onChange={e=>onSubmit(e)} type="select" id="category" name="category" defaultValue="all">
                                <option value="all">All</option>
                                <option value="videogames">Videogames</option>
                                <option value="websites">Websites</option>
                            </select>
                        </div>

                    <div className="header-heading-2">
                        <h4>Filter by state</h4>
                        <select onChange={e=>onSubmit(e)} type="select" id="status" name="status" defaultValue="all">
                            <option value="all">All</option>
                            <option value="pre_production">Pre-production</option>
                            <option value="production">Production</option>
                            <option value="constant_updates">Updating</option>
                            <option value="finished">Finished</option>
                        </select>
                    </div>

                </form>
            }

            </div>
    )
}

export default FiltersHeader