import { Link, NavLink, useLocation, useNavigate } from "react-router-dom"
import { useState } from 'react'

function CategoriesHeader({categories}){
    const location = useLocation()
    const navigate = useNavigate()

    const [term, setTerm] = useState("")
    const handleChange = (e) => {
        setTerm(e.target.value);
    }
    const onSubmit = (e) => {
        e.preventDefault();
        if (term.length >= 1){
            setTimeout(() => navigate("/search/" + term), 0.2);
            setTerm("");
        }else{
            displayError();
        }
    }

    function displayError(){
        let error = 'Debes ingresar al menos 1 carácter.';
        let e = document.getElementById('error');

        e.textContent = error
        console.log("error")
    }

    const [open, setOpen] = useState(false)

    return (
        <div className="second-header">

            <div className="header-heading">
                <h4>Categories</h4>
            </div>

            <div className='icon-box'>
                <i onClick={open ? ()=>{setOpen(false)}:()=>{setOpen(true)}} className={`bx ${open ? 'bx-x icon-2':'bx-menu icon-2'}`} id="icon"></i>
            </div>
                {
                    open ?
                    <div id="category-box" className="categories-box active-box">
                    <NavLink to="/blog" className={`${location.pathname.includes('/blog') ? "link active":"link"}`}>All</NavLink>

                    {
                        categories&&categories.map(category => (
                            <NavLink 
                            to={`/category/${category.slug}`} 
                            key={category.id} 
                            className={`${location.pathname === `category/${category.slug}`? "link active":"link"}`}
                            >{category.name}
                            </NavLink>
                        ))
                    }
                    
                    </div>
                    :
                    <div id="category-box" className="categories-box">
                    <NavLink to="/blog" className={`${location.pathname.includes('/blog') ? "link active":"link"}`}>All</NavLink>
                    {
                        categories&&categories.map(category => (
                            <NavLink 
                            to={`/category/${category.slug}`} 
                            key={category.id} 
                            className={`${location.pathname === `category/${category.slug}`?  "link active":"link"}`}
                            >{category.name}
                            </NavLink>
                        ))
                    }
                </div>
                }

                <div className="search-bar">
                    <form id="search-form" onSubmit={(e)=>onSubmit(e)} >
                        <input onChange={(e)=>handleChange(e)} value={term} id="search" name="search" type="search" placeholder="Search..." />
                    </form>
                    <button form="search-form"><i className='bx bx-search'></i></button>
                </div>
                <span id="error"></span>
            </div>
    )
}

export default CategoriesHeader