import { connect } from "react-redux";
import Layout from "hocs/layouts/Layout";
import { Link, useParams } from "react-router-dom";
import { useEffect } from "react";
import { get_project_detail } from "redux/actions/portfolio/portfolio";
import moment from "moment";
import DOMPurify from 'dompurify';

function ProjectDetail({
    get_project_detail,
    project
}) {
    const params = useParams()
    const slug = params.slug

    useEffect(()=>{
        window.scrollTo(0, 0);
        get_project_detail(slug);

        window.addEventListener('resize', adjustSize);
        return () => {
            window.addEventListener('resize', adjustSize);
        }
    }, [get_project_detail, slug]);

    function adjustSize(){
        const iframe = document.querySelector('iframe')

        if (iframe){
            var screenWidth = window.innerWidth;
            var screenHeight = window.innerHeight;
        
            if (screenWidth >= 1316) {
                iframe.width = '600';
                iframe.height = '350';
            } else if (screenWidth >= 820) {
                iframe.width = '500';
                iframe.height = '300';
            } else if (screenWidth >= 617) {
                iframe.width = '400';
                iframe.height = '250';
            }else if (screenWidth >= 474){
                iframe.width = '300';
                iframe.height = '200';
            }else if (screenWidth >= 316){
                iframe.width = '200';
                iframe.height = '175';
            }else{
                iframe.width = '175';
                iframe.height = '150';
            }
            
        };
    };
    
    return (
        <Layout>
            <section className="post-detail" >
                {
                    project&&project ?

                    <div>
                        <div className="img-post" >
                            <img src={`${process.env.REACT_APP_API_URL}/${project.thumbnail}`}  alt="post img" />
                        </div>

                        <h2 className="h2">{project.title}</h2>
                        <span className="span">{project.category.charAt(0).toUpperCase() + project.category.slice(1)}</span>
                        <span className="span">{moment(project.published).format('LL')}</span>
                        <p className="p">{project.description}</p>
                        <p className="editor" dangerouslySetInnerHTML={{ __html: DOMPurify.sanitize(project.content, {
                                            ADD_TAGS: ['iframe'],
                                            ADD_ATTR: ['allow', 'allowfullscreen', 'frameborder', 'scrolling', 'src'],
                                            ADD_URI_SAFE_ATTR: ['src'],
                                            FORBID_TAGS: ['script'],
                        })}} /> 
                    </div>
                    :
                    <section className="post-detail" >
                        <h3>Cargando...</h3>
                    </section>
                }
                    
                
            </section>
        </Layout>
    )
}

const mapStateToProps=state=>({
    project: state.portfolio.project
})

export default connect(mapStateToProps,{
    get_project_detail,
})(ProjectDetail)