import Layout from "hocs/layouts/Layout"
import logo from "assets/img/logo.png"
import Reveal from "components/Reveal"
import React, { useState } from 'react';
import { Helmet } from "react-helmet-async";
import { connect } from "react-redux";
import { get_portfolio_list, get_portfolio_list_page } from "redux/actions/portfolio/portfolio";
import { Link, useParams } from "react-router-dom";
import FiltersHeader from "components/portfolio/FiltersHeader";

function Portfolio({
    get_portfolio_list,
    get_portfolio_list_page,
    portfolio_list,
    count,
    next,
    previous

}) {

    const [loading, setLoading] = useState(false)

    let params = useParams()
    let currentPage = params.currentPage

    if (currentPage){

    }else{
        currentPage = 1
    }

    React.useEffect(() => {
        window.scrollTo(0, 0)  

        get_portfolio_list();
        get_portfolio_list_page(currentPage);

    }, [currentPage, get_portfolio_list, get_portfolio_list_page])
    return (
        <Layout>
        <Helmet>
        <title>Firu Dev | Portafolio</title>
        </Helmet>
    <FiltersHeader setLoading={setLoading}/>

        <section className="portfolio" id="portfolio">
        <div className="heading">
            <h2>Our <span>Projects</span></h2>
        </div>
        <div className="portfolio-container">
            
            {
                loading ?
                <h4>
                    Cargando...
                </h4>
                :
                <>
                {
                    portfolio_list ?
                    <>
                    {  
                        portfolio_list&&portfolio_list.map(project=>(
                            <Link to={`${project.slug}`} key={project.id} className="portfolio-box">
                                <img src={`${process.env.REACT_APP_API_URL}/${project.thumbnail}`} alt="logo" />
                                <div className="portfolio-layer">
                                    <h3>{project.title}</h3>
                                    <p>{project.description}</p>
                                    <Link to={`${project.slug}`}><i className='bx bx-link-external'></i></Link>
                                </div>
                            </Link>
                    ))
                    }
                    </>
                    :
                    <h4>No se encontraron proyectos.</h4>
                }
                </>
            }
            
            
        </div>
    </section>

        </Layout>
    )
}
const mapStateToProps = state =>({
    portfolio_list: state.portfolio.portfolio_list,
    count: state.portfolio.count,
    next: state.portfolio.next,
    previous: state.portfolio.previous,

})
export default connect(mapStateToProps, {
    get_portfolio_list,
    get_portfolio_list_page
})(Portfolio)