import axios from "axios";
import Layout from "hocs/layouts/Layout"
import React, { useState } from "react"
import { Helmet } from "react-helmet-async";
import { useDispatch } from "react-redux";
import { ADD_MSJ_MODAL } from "redux/actions/modal/types";
function Contact() {

    React.useEffect(() => {
        window.scrollTo(0, 0);    
    }, [])

    const [formData, setFormData] = useState({
        complete_name: '',
        email: '',
        mobile_number: '',
        subject: '',
        message: '',
    })

    const {
        complete_name,
        email,
        mobile_number,
        subject,
        message
    } = formData

    const onChange = e => {
        setFormData({ ...formData, [e.target.name]: e.target.value }); 
    };

    const dispatch = useDispatch()

    const onSubmit = e => {
        e.preventDefault();

        const sendEmail = async()=>{

            const formData = new FormData()
            formData.append('complete_name', complete_name)
            formData.append('email', email)
            formData.append('mobile_number', mobile_number)
            formData.append('subject', subject)
            formData.append('message', message)

            const config = {
                'Accept': 'application/json'
            }

            try {
                const res = await axios.post(`${process.env.REACT_APP_API_URL}/api/postman/send_contact_email`, formData, config);

                if (res.status === 200){
                    dispatch({
                        type: ADD_MSJ_MODAL,
                        payload: {
                            showModal: true,
                            message: 'Gracias por contactarnos, responderemos en breve. Enviamos una copia de la solicitud a tu correo electrónico.' 
                        }
                    });
                }else{
                    alert('Error al enviar el correo electrónico.')
                }

            }catch(err){
                alert('Error al enviar el correo electrónico.')
            }
        };

        sendEmail();
    }

    return (
        <Layout>
        <Helmet>
        <title>Firu Dev | Contacto</title>
        </Helmet>
    <section className="contact" id="contact">
        <h2 className="heading">Contact <span className="heading">Us</span></h2>

        <form onSubmit={(e)=>onSubmit(e)} encType="multipart/form-data">
            <div className="input-box">
                <input onChange={(e)=>onChange(e)}  type="text" name="complete_name" id="complete_name" value={complete_name} placeholder="Full Name" required />
                <input onChange={(e)=>onChange(e)}  type="email" name="email" id="email" value={email} placeholder="Email Address" required />
            </div>
            <div className="input-box">
                <input onChange={(e)=>onChange(e)}  type="number" name="mobile_number" id="mobile_number" value={mobile_number} placeholder="Mobile Number [Optional]" />
                <input onChange={(e)=>onChange(e)}  type="text" name="subject" id="subject" value={subject} placeholder="Subject" required />
            </div>
            <textarea onChange={(e)=>onChange(e)} name="message" id="message" cols="30" rows="10" placeholder="Your Message" required ></textarea>
            <input type="submit" value="Send Message" className="btn" />
        </form>
    </section>
        </Layout>
    )
}
export default Contact