import Layout from "hocs/layouts/Layout"
import { Link, Navigate } from 'react-router-dom';

import { useState } from 'react';
import { connect, useDispatch } from "react-redux";
import { load_user, login } from "redux/actions/auth/auth";
import { Helmet } from "react-helmet-async";
import { ADD_MSJ_MODAL, REMOVE_MODAL } from "redux/actions/modal/types";
import { GET_LOGIN_FAIL, GET_LOGIN_SUCCESS, REMOVE_AUTH_LOADING, SET_AUTH_LOADING } from "redux/actions/auth/types";
import axios from "axios";

function Login({
    login,
    isAuthenticated,
    loading
}) {

    const [formData, setFormData] = useState({
        email: '',
        password: ''
    });

    const {
        email,
        password
    } = formData;

    const onChange = e => setFormData({ ...formData, [e.target.name]: e.target.value });

    const dispatch = useDispatch();

    const onSubmit = e => {
        e.preventDefault();
        dispatch({
            type: ADD_MSJ_MODAL,
            payload: {
                showModal: true,
                message: 'Iniciando sesión.'
            }
        });

        const Login = async()=>{
            dispatch({
                type: SET_AUTH_LOADING
            });
            const config = {
                headers: {
                    'Content-type': 'application/json'
                }
            };
        
            const formData = new FormData()
            formData.append('email', email)
            formData.append('password', password)
        
            try {
                const res = await axios.post(`${process.env.REACT_APP_API_URL}/api/user/login`, formData, config);
                if (res.status === 200) {
                    dispatch({
                        type: REMOVE_AUTH_LOADING
                    });
                    dispatch({
                        type: GET_LOGIN_SUCCESS,
                        payload: res.data
                    });
                    dispatch({
                        type: REMOVE_MODAL,
                    });
                    dispatch(load_user());
                }else{
                    dispatch({
                        type: GET_LOGIN_FAIL,
                    });
                    dispatch({
                        type: REMOVE_AUTH_LOADING
                    })
                    dispatch({
                        type: ADD_MSJ_MODAL,
                        payload: {
                            showModal: true,
                            message: 'Email o contraseña inválidos.'
                        }
                    });
                }
            }catch(err){
                dispatch({
                    type: GET_LOGIN_FAIL,
                });
                dispatch({
                    type: REMOVE_AUTH_LOADING
                })
                dispatch({
                    type: ADD_MSJ_MODAL,
                    payload: {
                        showModal: true,
                        message: 'Error al iniciar sesión.'
                    }
                });
            }
        }
        Login();
    };

    if (!isAuthenticated) {
        // Redirigir al usuario a la página de inicio de sesión
    }else{
        return <Navigate to="/dashboard" />;
    };

    return (
        <Layout>
        <Helmet>
        <title>Firu Dev | Login </title>
        </Helmet>
    <section className="login" id="login">
            
        <div className="login-box">

            <h4>Firu <span className="text-primary">Dev</span>, Iniciar Sesión!</h4>
            <form onSubmit={e=>{onSubmit(e)}} action="#" encType="multipart/form-data">

                <h1>Email</h1>
                <input onChange={e=>{onChange(e)}} type="email" id="email" name="email" value={email} autoComplete="email" placeholder="Email" required />
                <h1>Contraseña</h1>
                <input onChange={e=>{onChange(e)}} type="password" id="password" name="password" value={password} autoComplete="current-password" placeholder="Contraseña" required />

                <Link to="/reset_password"><h1>Olvidaste tu contraseña?</h1></Link>

                <button type="submit" className="btn">Iniciar sesión</button>

            </form>

            </div>

    </section>
    </Layout>
    )
}

const mapStateToProps=state=>({
    isAuthenticated: state.auth.isAuthenticated,
    loading: state.auth.loading
})
export default connect(mapStateToProps, {
    login
}) (Login)