import PostBody from "components/blog/PostsBody";
import Layout from "hocs/layouts/Layout"
import { useEffect } from "react";
import { Helmet } from "react-helmet-async";
import { connect } from "react-redux";
import { Link, useParams } from 'react-router-dom'
import { get_search_blog, get_search_blog_page } from "redux/actions/blog/blog";

function Search({
    get_search_blog,
    get_search_blog_page,
    posts,
    count,
    next,
    previous,
}) {

    const params = useParams()
    const term = params.term

    let currentPage = params.currentPage

    if (currentPage){

    }else{
        currentPage = 1
    }
    useEffect(() => {
        window.scrollTo(0, 0);  
        get_search_blog(term)
        get_search_blog_page(term, currentPage)
    }, [get_search_blog, get_search_blog_page, term, currentPage])
    return (
        <Layout>
        <Helmet>
        <title>Firu Dev | Search </title>
        </Helmet>
        
        <section className="search" id="blog">
        
        <div className="heading-box">
        <h2 className="heading">Posts <span className="heading">Found</span></h2>
        <Link to="/blog" className="btn">Salir</Link>
        </div>
        <PostBody posts={posts&&posts} list_page={get_search_blog_page} count={count} />

    </section>

        </Layout>
    )
}
const mapStateToProps=state=>({
    posts: state.blog.filtered_posts,
    count: state.blog.count,
    next: state.blog.next,
    previous: state.blog.previous,
})
export default connect(mapStateToProps, {
    get_search_blog,
    get_search_blog_page,
}) (Search)